/** Anatomy Standard figure index (Jānis Šavlovskis & Kristaps Raits, CC BY-NC 4.0).
 *  Generated by scripts/import-anatomy-standard.mjs; images load from anatomystandard.com, unmodified. */

export const ANATOMY_STANDARD_ORIGIN = 'https://www.anatomystandard.com';
export const ANATOMY_STANDARD_LICENSE = 'https://creativecommons.org/licenses/by-nc/4.0/';

export interface StandardTerm {
  latin: string;
  english: string;
}

export interface StandardFigure {
  /** Width divided by height. */
  aspect: number;
  base: string;
  overlay: string;
  /** 'labels' overlays Latin terminology on the base; 'alternate' is a second view of the same structure. */
  overlayKind: 'labels' | 'alternate';
  alt: string;
  overlayAlt: string;
  caption: string;
  terms: StandardTerm[];
}

export interface StandardPage {
  title: string;
  figures: StandardFigure[];
}

let index: Promise<Record<string, StandardPage>> | null = null;

/** Figures for an Anatomy Standard page URL; the index loads on first use as its own chunk. */
export async function loadStandardPage(url: string): Promise<StandardPage | null> {
  index ??= import('./anatomy-standard.json').then(m => m.default.pages as Record<string, StandardPage>);
  const path = url.startsWith(ANATOMY_STANDARD_ORIGIN) ? url.slice(ANATOMY_STANDARD_ORIGIN.length) : url;
  return (await index)[path] ?? null;
}

export function standardImageUrl(path: string): string {
  return ANATOMY_STANDARD_ORIGIN + path;
}

/** Curated terms first, then every distinct term from the page's figure lists. */
export function mergeTerms(curated: StandardTerm[], page: StandardPage | null): StandardTerm[] {
  const seen = new Set(curated.map(t => t.latin.toLowerCase()));
  const extra = (page?.figures ?? []).flatMap(f => f.terms).filter(t => {
    const key = t.latin.toLowerCase();
    return seen.has(key) ? false : (seen.add(key), true);
  });
  return [...curated, ...extra];
}
